package com.masterclass.inventory.security; import org.springframework.context.annotation.*; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.provisioning.InMemoryUserDetailsManager; import org.springframework.security.web.SecurityFilterChain; @Configuration public class SecurityConfig { @Bean SecurityFilterChain filter(HttpSecurity http) throws Exception { return http.csrf(csrf->csrf.disable()).authorizeHttpRequests(auth->auth.requestMatchers("/actuator/health","/swagger-ui.html","/swagger-ui/**","/v3/api-docs/**").permitAll().anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).build(); } @Bean UserDetailsService users(){ UserDetails admin=User.withUsername("admin").password("{noop}admin123").roles("ADMIN").build(); return new InMemoryUserDetailsManager(admin); } }
